function renderData(){$('#view-data').innerHTML=`<div class="panel"><h2>导入成绩文件</h2><p class="hint">支持多次导入考试。每场考试可单独设置名称、权重和总分。</p><input id="xlsxInput" class="file-input" type="file" accept=".xlsx"><div id="importResult"></div></div><div class="panel"><h2>已导入考试 <span class="badge">${state.exams.length}次</span></h2>${orderedExams().map(e=>`<div class="exam-editor" data-exam-editor="${esc(e.id)}"><div class="grid"><div class="field"><label>考试名称</label><input data-exam-field="name" value="${esc(e.name||'')}"></div><div class="field"><label>考试日期</label><input data-exam-field="date" type="date" value="${esc(e.date||'')}"></div><div class="field"><label>总分</label><input data-exam-field="totalScore" type="number" min="1" value="${Number(e.totalScore)||100}"></div><div class="field"><label>点名权重</label><input data-exam-field="weight" type="number" min="0" step="0.1" value="${Number(e.weight??1)}"></div></div><div class="actions"><button class="primary" data-save-exam="${esc(e.id)}">保存考试设置</button><button class="danger" data-delete-exam="${esc(e.id)}">删除考试</button></div></div>`).join('')||'<div class="empty">尚未导入考试</div>'}</div><div class="panel"><h2>备份与恢复</h2><div class="actions"><button class="secondary" id="backupBtn">导出完整备份</button><button class="secondary" id="historyExportBtn">导出点名历史</button><label class="secondary">选择备份<input id="backupInput" type="file" accept=".json" hidden></label></div></div>`;$('#xlsxInput')?.addEventListener('change',handleImport);$('#backupBtn')?.addEventListener('click',exportBackup);$('#historyExportBtn')?.addEventListener('click',exportHistory);$('#backupInput')?.addEventListener('change',handleRestore);$$('[data-save-exam]').forEach(b=>b.onclick=async()=>{const box=b.closest('[data-exam-editor]'),e=state.exams.find(x=>x.id===b.dataset.saveExam);if(!e)return;for(const field of ['name','date','totalScore','weight']){const input=box.querySelector(`[data-exam-field="${field}"]`);e[field]=field==='name'||field==='date'?input.value:Number(input.value);}await DB.put('exams',e);await reload();toast('考试设置已保存');});$$('[data-delete-exam]').forEach(b=>b.onclick=async()=>{const e=state.exams.find(x=>x.id===b.dataset.deleteExam);if(!e||!confirm(`确定删除考试“${e.name}”及其成绩吗？`))return;await DB.remove('exams',e.id);for(const r of state.examResults.filter(x=>x.examId===e.id))await DB.remove('examResults',r.id);await reload();toast('考试已删除');});}
// Updated compact roll-call view: show latest exam score, while the algorithm uses weighted recent averages.
function renderRollcall(){const inClass=state.students.filter(s=>s.className===state.currentClass),currentExam=orderedExams()[0],label=['','简单','适中','困难'][state.difficulty]||'适中';$('#view-rollcall').innerHTML=`<div class="panel hero"><div class="class-name">${inClass.length?`本班 ${inClass.length} 人`:'还没有学生资料'}</div><div class="field"><label>题目难度</label><div class="difficulty-buttons"><button class="secondary difficulty-button ${!state.selectedCandidate&&state.difficulty===1?'active':''}" data-difficulty="1">简单</button><button class="secondary difficulty-button ${!state.selectedCandidate&&state.difficulty===2?'active':''}" data-difficulty="2">适中</button><button class="secondary difficulty-button ${!state.selectedCandidate&&state.difficulty===3?'active':''}" data-difficulty="3">困难</button></div></div><div class="question">${state.selectedCandidate?'单击难度按钮继续点名':'选择难度后生成候选'}</div></div><div class="panel"><h2>本次候选</h2><div class="candidate-list">${state.candidates.length?state.candidates.map(c=>{const latest=examResult(currentExam,c.student)||c.student;return `<button class="candidate ${state.selectedCandidate===c.student.id?'selected-candidate':''}" data-student="${esc(c.student.id)}"><span><strong>${esc(c.student.displayName||c.student.name)}</strong><small>${latest.score??'—'}分 · 班次 ${latest.classRank??'—'}</small></span><span class="score">近期点名次数：${c.recentCount}</span></button>`}).join(''):'<div class="empty">选择上方难度后生成候选</div>'}</div></div>`;$$('[data-difficulty]').forEach(b=>b.onclick=()=>{state.difficulty=Number(b.dataset.difficulty);state.selectedCandidate=null;recommend();});$$('.candidate').forEach(b=>b.onclick=()=>selectStudent(b.dataset.student));}
function historyScope(){return state.students.filter(s=>s.className===state.currentClass);}
function renderHistory(){const classStudents=historyScope(),ids=new Set(classStudents.map(s=>s.id)),timeline=state.history.filter(x=>ids.has(x.studentId)).sort((a,b)=>String(b.at).localeCompare(String(a.at)));if(state.historyStudentId){const s=classStudents.find(x=>x.id===state.historyStudentId);const records=timeline.filter(x=>x.studentId===state.historyStudentId);$('#view-history').innerHTML=`<div class="panel"><button class="secondary" id="backHistory">返回统计</button><h2>${esc(s?.displayName||s?.name||'学生')}</h2></div><div class="panel"><h3>全部点名记录</h3>${records.length?records.map(x=>`<div class="stat-row history-row"><span>${new Date(x.at).toLocaleString()}</span><span>${['','简单','适中','困难'][x.difficulty]||'—'}</span><span>${esc(x.className||'')}</span></div>`).join(''):'<div class="empty">暂无点名记录</div>'}</div>`;$('#backHistory').onclick=()=>{state.historyStudentId='';renderHistory();};return;}const counts=new Map();timeline.forEach(x=>counts.set(x.studentId,(counts.get(x.studentId)||0)+1));const rows=[...classStudents].sort((a,b)=>(counts.get(b.id)||0)-(counts.get(a.id)||0));$('#view-history').innerHTML=`<div class="panel"><div class="stats-switch"><button class="secondary ${state.statsMode==='timeline'?'active':''}" id="timelineBtn">点名时间</button><button class="secondary ${state.statsMode==='counts'?'active':''}" id="countsBtn">学生总次数</button></div><div class="field"><label>本班总点名次数</label><input disabled value="${timeline.length}"></div></div>${state.statsMode==='timeline'?`<div class="panel"><h2>点名时间</h2>${timeline.length?timeline.map(x=>{const s=classStudents.find(st=>st.id===x.studentId);return `<div class="stat-row history-row"><span><button class="student-link" data-history-student="${esc(x.studentId)}">${esc(s?.displayName||s?.name||x.studentId)}</button><br><small class="hint">${esc(s?.className||x.className||'')}</small></span><span>${new Date(x.at).toLocaleString()}</span><span>${['','简单','适中','困难'][x.difficulty]||'—'}</span></div>`}).join(''):'<div class="empty">暂无点名记录</div>'}</div>`:`<div class="panel"><h2>学生总点名次数</h2>${rows.length?rows.map(s=>`<div class="stat-row history-row"><span><button class="student-link" data-history-student="${esc(s.id)}">${esc(s.displayName||s.name)}</button></span><span>${counts.get(s.id)||0}次</span><span>${s.focus?'关注':''}</span></div>`).join(''):'<div class="empty">本班暂无学生</div>'}</div>`}`;$('#timelineBtn').onclick=()=>{state.statsMode='timeline';renderHistory();};$('#countsBtn').onclick=()=>{state.statsMode='counts';renderHistory();};$$('[data-history-student]').forEach(b=>b.onclick=()=>{state.historyStudentId=b.dataset.historyStudent;renderHistory();});}
