function renderHistory(){const classStudents=historyScope(),ids=new Set(classStudents.map(s=>s.id)),timeline=state.history.filter(x=>ids.has(x.studentId)).sort((a,b)=>String(b.at).localeCompare(String(a.at)));if(state.historyStudentId){const s=classStudents.find(x=>x.id===state.historyStudentId),records=timeline.filter(x=>x.studentId===state.historyStudentId);$('#view-history').innerHTML=`<div class="panel"><button class="secondary" id="backHistory">返回统计</button><h2>${esc(s?.displayName||s?.name||'学生')}</h2></div><div class="panel"><h3>全部点名记录</h3>${records.length?records.map(x=>`<div class="stat-row history-row"><span>${new Date(x.at).toLocaleString()}</span><span>${['','简单','适中','困难'][x.difficulty]||'—'}</span><span>${esc(x.className||'')}</span></div>`).join(''):'<div class="empty">暂无点名记录</div>'}</div>`;$('#backHistory').onclick=()=>{state.historyStudentId='';renderHistory();};return;}const counts=new Map();timeline.forEach(x=>counts.set(x.studentId,(counts.get(x.studentId)||0)+1));const rows=[...classStudents].sort((a,b)=>(counts.get(b.id)||0)-(counts.get(a.id)||0));const lastCallMap=new Map();timeline.forEach(x=>{if(!lastCallMap.has(x.studentId))lastCallMap.set(x.studentId,x.at);});const difficultyCounts=[1,2,3].map(level=>timeline.filter(x=>Number(x.difficulty)===level).length);$('#view-history').innerHTML=`<div class="panel"><div class="stats-switch"><button class="secondary ${state.statsMode==='timeline'?'active':''}" id="timelineBtn">点名时间</button><button class="secondary ${state.statsMode==='counts'?'active':''}" id="countsBtn">学生总次数</button></div><div class="field"><label>本班总点名次数</label><input disabled value="${timeline.length}"></div></div><div class="panel difficulty-stats"><h2>题目难度统计</h2><div class="difficulty-chart"><canvas id="difficultyChart" width="220" height="220"></canvas><div class="difficulty-legend"><div><i class="legend-dot easy"></i>简单：${difficultyCounts[0]}次</div><div><i class="legend-dot medium"></i>适中：${difficultyCounts[1]}次</div><div><i class="legend-dot hard"></i>困难：${difficultyCounts[2]}次</div></div></div></div>${state.statsMode==='timeline'?`<div class="panel"><h2>点名时间</h2>${timeline.length?timeline.map(x=>{const s=classStudents.find(st=>st.id===x.studentId);return `<div class="stat-row history-row"><span><button class="student-link" data-history-student="${esc(x.studentId)}">${esc(s?.displayName||s?.name||x.studentId)}</button><br><small class="hint">${esc(s?.className||x.className||'')}</small></span><span>${new Date(x.at).toLocaleString()}</span><span>${['','简单','适中','困难'][x.difficulty]||'—'}</span></div>`}).join(''):'<div class="empty">暂无点名记录</div>'}</div>`:`<div class="panel"><h2>学生总点名次数</h2>${rows.length?rows.map(s=>`<div class="stat-row history-row"><span><button class="student-link" data-history-student="${esc(s.id)}">${esc(s.displayName||s.name)}</button></span><span>${counts.get(s.id)||0}次</span><span>${lastCallMap.has(s.id)?`上次：${relativeCallTime(lastCallMap.get(s.id))}`:'未点名'}</span></div>`).join(''):'<div class="empty">本班暂无学生</div>'}</div>`}`;drawDifficultyPie(difficultyCounts);$('#timelineBtn').onclick=()=>{state.statsMode='timeline';renderHistory();};$('#countsBtn').onclick=()=>{state.statsMode='counts';renderHistory();};$$('[data-history-student]').forEach(b=>b.onclick=()=>{state.historyStudentId=b.dataset.historyStudent;renderHistory();});}

