async function markSelectedAbsent(){
  const id=state.selectedCandidate;
  if(!id)return;
  const latest=[...state.history].filter(x=>x.studentId===id).sort((a,b)=>Date.parse(b.at)-Date.parse(a.at))[0];
  if(latest?.id!==undefined){await DB.remove('history',latest.id);state.history=state.history.filter(x=>x.id!==latest.id);}
  const absenceId=`${id}-${localDate()}`;
  await DB.put('absences',{id:absenceId,studentId:id,date:localDate()});
  state.absences=state.absences.filter(x=>!(x.studentId===id&&x.date===localDate()));
  state.absences.push({id:absenceId,studentId:id,date:localDate()});
  state.selectedCandidate=null;state.candidates=[];renderRollcall();toast('已撤销本次点名并标记今日缺席');
}

function drawScoreChart(student,records){
  const canvas=$('#scoreChart');if(!canvas||!records.length)return;
  const logicalHeight=300,logicalWidth=Math.max(760,records.length*120),dpr=Math.max(1,window.devicePixelRatio||1);
  canvas.width=Math.round(logicalWidth*dpr);canvas.height=Math.round(logicalHeight*dpr);canvas.style.width=`${logicalWidth}px`;canvas.style.height=`${logicalHeight}px`;
  const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,logicalWidth,logicalHeight);
  const p={left:48,right:24,top:30,bottom:42},scores=records.map(x=>Number(x.result.score)||0);
  const avgs=records.map(x=>{const vals=state.examResults.filter(r=>r.examId===x.exam.id).map(r=>Number(r.result?.score)).filter(Number.isFinite);return vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:0;});
  const max=Math.max(100,...scores,...avgs),plotW=logicalWidth-p.left-p.right,plotH=logicalHeight-p.top-p.bottom;
  const x=i=>p.left+(records.length===1?plotW/2:i*plotW/(records.length-1)),y=v=>p.top+plotH-(v/max)*plotH,fmt=v=>Number.isInteger(v)?String(v):v.toFixed(1);
  ctx.font='12px sans-serif';ctx.textAlign='right';ctx.fillStyle='#6b7c78';ctx.strokeStyle='#dfe9e6';ctx.lineWidth=1;
  for(let i=0;i<=4;i++){const value=max*i/4,yy=y(value);ctx.beginPath();ctx.moveTo(p.left,yy);ctx.lineTo(logicalWidth-p.right,yy);ctx.stroke();ctx.fillText(fmt(value),p.left-7,yy+4);}
  const line=(values,color,offset)=>{ctx.strokeStyle=color;ctx.lineWidth=2.5;ctx.beginPath();values.forEach((v,i)=>{i?ctx.lineTo(x(i),y(v)):ctx.moveTo(x(i),y(v));});ctx.stroke();values.forEach((v,i)=>{ctx.fillStyle=color;ctx.beginPath();ctx.arc(x(i),y(v),4,0,Math.PI*2);ctx.fill();ctx.textAlign='center';ctx.font='12px sans-serif';ctx.fillText(fmt(v),x(i),y(v)+offset);});};
  line(avgs,'#16302b',-9);line(scores,'#b42318',17);
  ctx.fillStyle='#16302b';ctx.textAlign='left';ctx.font='bold 12px sans-serif';ctx.fillText('班级均分',p.left,16);ctx.fillStyle='#b42318';ctx.fillText('个人得分',p.left+78,16);
  ctx.fillStyle='#6b7c78';ctx.font='11px sans-serif';records.forEach((r,i)=>{ctx.textAlign='center';ctx.fillText(String(r.exam.date||''),x(i),logicalHeight-16);});
}

