// Current-exam selection always derives the immediately older exam.
function previousExamIdFor(currentId){
  const exams=orderedExams(), index=exams.findIndex(e=>e.id===currentId);
  return index>=0 ? (exams[index+1]?.id||'') : (exams[1]?.id||'');
}

function sortArrow(active, direction){return active ? (direction==='asc'?' ↑':' ↓') : '';}

function studentSortValue(student){
  const exams=orderedExams(), current=exams.find(e=>e.id===state.studentCurrentExamId)||exams[0], previous=exams.find(e=>e.id===state.studentPreviousExamId)||exams[1];
  if(state.studentSort.startsWith('score'))return Number(examResult(current,student)?.score??-1);
  if(state.studentSort.startsWith('average'))return Number(averageScoreRate(student)??-1);
  if(state.studentSort.startsWith('rank')){const now=rankNumber(examResult(current,student)?.gradeRank),old=rankNumber(examResult(previous,student)?.gradeRank);return now===null||old===null?null:old-now;}
  return String(student.name||'');
}
function sortedStudents(rows){
  const direction=state.studentSort.endsWith('asc')?1:-1;
  return [...rows].sort((a,b)=>{const av=studentSortValue(a),bv=studentSortValue(b);if(typeof av==='string')return av.localeCompare(bv,'zh-CN')*direction; if(av===null&&bv!==null)return 1;if(av!==null&&bv===null)return -1;return ((av??0)-(bv??0))*direction||String(a.name).localeCompare(String(b.name),'zh-CN');});
}
function toggleStudentHeader(key){const prefix=key;state.studentSort=state.studentSort.startsWith(prefix)&&state.studentSort.endsWith('desc')?`${prefix}-asc`:`${prefix}-desc`;renderStudents();}

