  const all=[...state.history].filter(x=>state.students.some(s=>s.id===x.studentId&&(!state.currentClass||s.className===state.currentClass))).sort((a,b)=>String(b.at).localeCompare(String(a.at))),rule=state.historyFilter||'all';
